package subtitle

import (
	"embed"
	"encoding/json"
	"fmt"
	"sync"
)

// The data files are generated by internal/cmd/subzerogen; each records
// its origin and license.
//
//go:embed data/*.json
var dataFiles embed.FS

// loadData decodes an embedded data file. The files are part of the
// binary, so a failure is a build defect.
func loadData[T any](name string) T {
	var v T
	data, err := dataFiles.ReadFile("data/" + name)
	if err == nil {
		err = json.Unmarshal(data, &v)
	}
	if err != nil {
		panic(fmt.Sprintf("subtitle: embedded %s: %v", name, err))
	}
	return v
}

// ocrGroup is one of Subzero's OCR fix dictionaries of a language, as
// replacement pairs in the order Subzero tries them.
type ocrGroup [][2]string

// ocrDictionaries are Subzero's OCR fix dictionaries by ISO 639-2/T code.
var ocrDictionaries = sync.OnceValue(func() map[string]*ocrDictionary {
	file := loadData[struct {
		Languages map[string]map[string]ocrGroup `json:"languages"`
	}]("ocr.json")
	dicts := make(map[string]*ocrDictionary, len(file.Languages))
	for lang, groups := range file.Languages {
		dicts[lang] = newOCRDictionary(groups)
	}
	return dicts
})
